import 'package:local_auth/local_auth.dart';import 'package:flutter/services.dart';import 'package:flutter/foundation.dart';import 'secure_storage_service.dart';enum BiometricType {  fingerprint,  face,  iris,  strong,  weak,  unknown,}class BiometricAuthService {  static final LocalAuthentication _auth = LocalAuthentication();  static Future<bool> isBiometricAvailable() async {    try {      return await _auth.canCheckBiometrics;    } catch (e) {      debugPrint('Biometric availability check failed: $e');      return false;    }  }  static Future<List<BiometricType>> getAvailableBiometrics() async {    try {      final available = await _auth.getAvailableBiometrics();      return available.map(_mapBiometricType).toList();    } catch (e) {      debugPrint('Failed to get available biometrics: $e');      return [];    }  }  static BiometricType _mapBiometricType(dynamic type) {    // local_auth 3.x returns BiometricType enum from the plugin    if (type == null) return BiometricType.unknown;    final typeStr = type.toString().split('.').last;    switch (typeStr) {      case 'fingerprint':        return BiometricType.fingerprint;      case 'face':        return BiometricType.face;      case 'iris':        return BiometricType.iris;      case 'strong':        return BiometricType.strong;      case 'weak':        return BiometricType.weak;      default:        return BiometricType.unknown;    }  }  static Future<BiometricType?> getEnabledBiometricType() async {    final typeStr = await SecureStorageService.getBiometricType();    if (typeStr == null) return null;    return BiometricType.values.firstWhere(      (e) => e.name == typeStr,      orElse: () => BiometricType.unknown,    );  }  static Future<void> disableBiometric() async {    await SecureStorageService.setBiometricEnabled(false);  }  static Future<BiometricAuthResult> authenticate({    required String localizedReason,    bool useErrorDialogs = true,    bool stickyAuth = true,    bool sensitiveTransaction = false,  }) async {    try {      final isAvailable = await isBiometricAvailable();      if (!isAvailable) {        return BiometricAuthResult(          success: false,          errorCode: BiometricAuthErrorCode.notAvailable,          errorMessage: 'Biometric authentication is not available on this device',        );      }      final availableBiometrics = await getAvailableBiometrics();      if (availableBiometrics.isEmpty) {        return BiometricAuthResult(          success: false,          errorCode: BiometricAuthErrorCode.notEnrolled,          errorMessage: 'No biometrics enrolled on this device',        );      }      final authenticated = await _auth.authenticate(        localizedReason: localizedReason,        options: AuthenticationOptions(          stickyAuth: stickyAuth,          sensitiveTransaction: sensitiveTransaction,          useErrorDialogs: useErrorDialogs,        ),      );      if (authenticated) {        await SecureStorageService.setBiometricEnabled(true);        final biometricType = availableBiometrics.first;        await SecureStorageService.setBiometricType(biometricType.name);        return BiometricAuthResult(          success: true,          biometricType: biometricType,        );      } else {        return BiometricAuthResult(          success: false,          errorCode: BiometricAuthErrorCode.userCancel,          errorMessage: 'Authentication was cancelled by user',        );      }    } on PlatformException catch (e) {      return _handlePlatformException(e);    } catch (e) {      debugPrint('Biometric authentication error: $e');      return BiometricAuthResult(        success: false,        errorCode: BiometricAuthErrorCode.unknown,        errorMessage: e.toString(),      );    }  }  static BiometricAuthResult _handlePlatformException(PlatformException e) {    switch (e.code) {      case 'NotAvailable':        return BiometricAuthResult(          success: false,          errorCode: BiometricAuthErrorCode.notAvailable,          errorMessage: 'Biometric authentication is not available',        );      case 'NotEnrolled':        return BiometricAuthResult(          success: false,          errorCode: BiometricAuthErrorCode.notEnrolled,          errorMessage: 'No biometrics enrolled',        );      case 'LockedOut':        return BiometricAuthResult(          success: false,          errorCode: BiometricAuthErrorCode.lockedOut,          errorMessage: 'Biometric authentication locked out',        );      case 'PermanentlyLockedOut':        return BiometricAuthResult(          success: false,          errorCode: BiometricAuthErrorCode.permanentlyLockedOut,          errorMessage: 'Biometric authentication permanently locked out',        );      default:        return BiometricAuthResult(          success: false,          errorCode: BiometricAuthErrorCode.unknown,          errorMessage: e.message ?? 'Unknown error',        );    }  }  static Future<bool> isBiometricEnabled() async {    return await SecureStorageService.isBiometricEnabled();  }  static Future<void> setBiometricEnabled(bool enabled) async {    await SecureStorageService.setBiometricEnabled(enabled);  }}class BiometricAuthResult {  final bool success;  final BiometricType? biometricType;  final BiometricAuthErrorCode? errorCode;  final String? errorMessage;  BiometricAuthResult({    required this.success,    this.biometricType,    this.errorCode,    this.errorMessage,  });}enum BiometricAuthErrorCode {  notAvailable,  notEnrolled,  lockedOut,  permanentlyLockedOut,  userCancel,  systemCancel,  passcodeNotSet,  unknown,}